/// `CameraInstruction` gives a custom camera specific instructions to operate.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct CameraInstruction {
    /// Set is a camera instruction that sets the camera to a specified preset.
    pub set: Option<CameraInstructionSet>,
    /// Clear can be set to true to clear all the current camera instructions.
    pub clear: Option<bool>,
    /// Fade is a camera instruction that fades the screen to a specified colour.
    pub fade: Option<CameraInstructionFade>,
    /// Target is a camera instruction that targets a specific entity.
    pub target: Option<CameraInstructionTarget>,
    /// `RemoveTarget` can be set to true to remove the current aim assist target.
    pub remove_target: Option<bool>,
    /// `FieldOfView` is a camera instruction that updates the field of view for the camera.
    pub field_of_view: Option<CameraInstructionFieldOfView>,
    /// Spline is a camera instruction that creates a spline path for the camera to follow.
    pub spline: Option<CameraSplineInstruction>,
    /// `AttachToEntity` is the entity ID to attach the camera to.
    pub attach_to_entity: Option<i64>,
    /// `DetachFromEntity` can be set to true to detach the camera from the current entity.
    pub detach_from_entity: Option<bool>,
}

impl Codec for CameraInstruction {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        Ok(Self {
            set: if r.bool()? {
                Some(CameraInstructionSet::decode(r)?)
            } else {
                None
            },
            clear: if r.bool()? { Some(r.bool()?) } else { None },
            fade: if r.bool()? {
                Some(CameraInstructionFade::decode(r)?)
            } else {
                None
            },
            target: if r.bool()? {
                Some(CameraInstructionTarget::decode(r)?)
            } else {
                None
            },
            remove_target: if r.bool()? { Some(r.bool()?) } else { None },
            field_of_view: if r.bool()? {
                Some(CameraInstructionFieldOfView::decode(r)?)
            } else {
                None
            },
            spline: if r.bool()? {
                Some(CameraSplineInstruction::decode(r)?)
            } else {
                None
            },
            attach_to_entity: if r.bool()? {
                Some(r.actor_unique_id_int64()?)
            } else {
                None
            },
            detach_from_entity: if r.bool()? { Some(r.bool()?) } else { None },
        })
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.bool(self.set.is_some());
        if let Some(v) = &self.set {
            v.encode(w)?;
        }
        w.bool(self.clear.is_some());
        if let Some(v) = self.clear {
            w.bool(v);
        }
        w.bool(self.fade.is_some());
        if let Some(v) = &self.fade {
            v.encode(w)?;
        }
        w.bool(self.target.is_some());
        if let Some(v) = &self.target {
            v.encode(w)?;
        }
        w.bool(self.remove_target.is_some());
        if let Some(v) = self.remove_target {
            w.bool(v);
        }
        w.bool(self.field_of_view.is_some());
        if let Some(v) = &self.field_of_view {
            v.encode(w)?;
        }
        w.bool(self.spline.is_some());
        if let Some(v) = &self.spline {
            v.encode(w)?;
        }
        w.bool(self.attach_to_entity.is_some());
        if let Some(v) = self.attach_to_entity {
            w.actor_unique_id_int64(v);
        }
        w.bool(self.detach_from_entity.is_some());
        if let Some(v) = self.detach_from_entity {
            w.bool(v);
        }
        Ok(())
    }
}

