    /// Whether clients send the packet with this ID (gophertunnel's client packet pool). A server accepts only packets from clients.
    pub const fn is_from_client(id: u32) -> bool {
        matches!(id, 1 | 4 | 8 | 9 | 19 | 21 | 27 | 30 | 31 | 33..=36 | 41 | 44..=47 | 55 | 56 | 62 | 64 | 68 | 69 | 74 | 75 | 77 | 78 | 84 | 90 | 92..=95 | 97 | 98 | 101 | 102 | 105 | 109 | 113 | 115 | 117 | 123 | 125 | 129 | 131..=133 | 135 | 138..=141 | 144 | 147 | 151 | 152 | 154..=156 | 163 | 171 | 173 | 175 | 177 | 178 | 184 | 185 | 190 | 193 | 195 | 303 | 306 | 307 | 312 | 315 | 321..=323 | 329 | 332 | 340 | 342 | 343 | 350 | 351)
    }

    /// Whether servers send the packet with this ID (gophertunnel's server packet pool). A server accepts only packets from clients.
    pub const fn is_from_server(id: u32) -> bool {
        matches!(id, 1..=19 | 21 | 22 | 25..=36 | 38..=52 | 54..=56 | 58..=70 | 72..=115 | 117..=119 | 121..=125 | 129..=133 | 135..=199 | 300 | 302..=310 | 312..=318 | 320..=331 | 333..=339 | 341 | 344..=349 | 351 | 352)
    }

    /// Decodes the payload of a packet with this ID: the bytes after the packet header. Every byte must be part of the packet.
    ///
    /// `budget` is the allocation budget left for the batch the packet came in (PLAN.md 10.1); decoding takes what the packet allocates from it. `shield_id` is the shield's item network ID, which changes the item wire format.
    pub fn decode(id: u32, payload: &[u8], budget: &mut usize, shield_id: i32) -> Result<Self> {
        let mut r = Reader::new(payload, *budget, shield_id);
        let packet = Self::decode_body(id, &mut r);
        *budget = r.budget();
        let packet = packet?;
        if !r.remaining().is_empty() {
            return Err(Error::InvalidValue {
                field: "packet",
                reason: "bytes after the packet",
            });
        }
        Ok(packet)
    }

    #[expect(
        clippy::too_many_lines,
        reason = "consistency: generated from one gophertunnel body or table"
    )]
